#include "compress.h"
#include <stdint.h>
#include <string.h>

static uint32_t crc32_of(const unsigned char *data, int size) {
    uint32_t crc = 0xffffffffu;
    for (int i = 0; i < size; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++)
            crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1u)));
    }
    return ~crc;
}

static unsigned char *emit_varint(unsigned char *output, unsigned int value) {
    while (value >= 0x80) {
        *output++ = (unsigned char)((value & 0x7f) | 0x80);
        value >>= 7;
    }
    *output++ = (unsigned char)value;
    return output;
}

int compressBound(int inputSize) {
    if (inputSize < 0) return -1;
    return inputSize + 17;
}

int compress(const char *source, char *dest, int sourceSize) {
    if (sourceSize < 0 || !dest || (!source && sourceSize)) return -1;
    const unsigned char *input = (const unsigned char *)source;
    unsigned char *output = (unsigned char *)dest;

    *output++ = 0xd7; *output++ = 0x9c; *output++ = 0x01;
    *output++ = (unsigned char)((uint32_t)sourceSize >> 24);
    *output++ = (unsigned char)((uint32_t)sourceSize >> 16);
    *output++ = (unsigned char)((uint32_t)sourceSize >> 8);
    *output++ = (unsigned char)sourceSize;

    if (sourceSize < 15) {
        *output++ = (unsigned char)(sourceSize << 4);
    } else {
        *output++ = 0xf0;
        output = emit_varint(output, (unsigned int)(sourceSize - 15));
    }
    if (sourceSize) {
        memcpy(output, input, (size_t)sourceSize);
        output += sourceSize;
    }

    uint32_t crc = crc32_of(input, sourceSize);
    *output++ = (unsigned char)crc;
    *output++ = (unsigned char)(crc >> 8);
    *output++ = (unsigned char)(crc >> 16);
    *output++ = (unsigned char)(crc >> 24);
    return (int)(output - (unsigned char *)dest);
}
